const $=(s,c=document)=>c.querySelector(s); const $$=(s,c=document)=>[...c.querySelectorAll(s)]; const store={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
requestAnimationFrame(()=>document.body.classList.add('page-enter'));
const originals=new Map(); $$('[data-i18n]').forEach(el=>originals.set(el,el.textContent));
function applyLanguage(lang){if(!['ru','ky','en','es'].includes(lang))lang='ru'; document.documentElement.lang=lang; document.body.dataset.lang=lang; const dict=translations[lang]||{}; $$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n; el.textContent=lang==='ru'?(originals.get(el)||el.textContent):(dict[key]||originals.get(el)||el.textContent);}); $$('[data-lang-switch]').forEach(sw=>{const f=$('[data-current-flag]',sw),l=$('[data-current-lang]',sw); if(f)f.src=flagMap[lang]; if(l)l.textContent=labelMap[lang]; $$('[data-lang]',sw).forEach(b=>b.classList.toggle('is-active',b.dataset.lang===lang));}); store.set('smmkadr_lang',lang); window.dispatchEvent(new CustomEvent('smm:language',{detail:{lang}}));}
let currentLang=store.get('smmkadr_lang')||'ru'; applyLanguage(currentLang);
$$('[data-lang-toggle]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation(); const sw=btn.closest('[data-lang-switch]'); const open=!sw.classList.contains('is-open'); $$('[data-lang-switch]').forEach(x=>x.classList.remove('is-open')); sw.classList.toggle('is-open',open); btn.setAttribute('aria-expanded',String(open));}));
$$('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>{currentLang=btn.dataset.lang; applyLanguage(currentLang); $$('[data-lang-switch]').forEach(x=>x.classList.remove('is-open'));})); document.addEventListener('click',()=>$$('[data-lang-switch]').forEach(x=>x.classList.remove('is-open')));
const header=$('[data-header]'),progress=$('.scroll-progress span'); function onScroll(){const y=scrollY||document.documentElement.scrollTop; header?.classList.toggle('is-scrolled',y>18); const max=document.documentElement.scrollHeight-innerHeight; if(progress)progress.style.width=(max>0?y/max*100:0)+'%';} onScroll(); addEventListener('scroll',onScroll,{passive:true});
const menu=$('[data-menu]'),menuOpen=$('[data-menu-open]'); function setMenu(open){menu?.classList.toggle('is-open',open); menu?.setAttribute('aria-hidden',String(!open)); menuOpen?.setAttribute('aria-expanded',String(open)); document.body.style.overflow=open?'hidden':'';} menuOpen?.addEventListener('click',()=>setMenu(true)); $$('[data-menu-close],.mobile-menu nav a').forEach(el=>el.addEventListener('click',()=>setMenu(false))); addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches; const reveals=$$('.reveal'); if(reduced||!('IntersectionObserver'in window))reveals.forEach(x=>x.classList.add('is-visible')); else{const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target)}}),{threshold:.1,rootMargin:'0px 0px -40px'});reveals.forEach(x=>io.observe(x));}
if(matchMedia('(pointer:fine)').matches)$$('.pointer-glow').forEach(card=>card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.style.setProperty('--mx',e.clientX-r.left+'px');card.style.setProperty('--my',e.clientY-r.top+'px')}));
const tilt=$('[data-tilt]'); if(tilt&&!reduced&&matchMedia('(pointer:fine)').matches){tilt.parentElement.addEventListener('pointermove',e=>{const r=tilt.parentElement.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;tilt.style.transform=`perspective(900px) rotateY(${x*7}deg) rotateX(${-y*6}deg)`});tilt.parentElement.addEventListener('pointerleave',()=>tilt.style.transform='')}
const modal=$('[data-team-modal]'); function openMember(id){const m=team[id];if(!m||!modal)return;const lang=document.body.dataset.lang||'ru',d=m[lang]||m.ru; $('[data-modal-image]',modal).src=m.image;$('[data-modal-image]',modal).alt=m.name;$('[data-modal-name]',modal).textContent=m.name;$('[data-modal-department]',modal).textContent=d.dept;$('[data-modal-role]',modal).textContent=d.role;$('[data-modal-bio]',modal).textContent=d.bio;const skills=$('[data-modal-skills]',modal);skills.replaceChildren(...d.skills.map(s=>{const x=document.createElement('span');x.textContent=s;return x}));document.body.style.overflow='hidden'; if(modal.showModal)modal.showModal();else modal.setAttribute('open','');} function closeMember(){if(!modal)return;document.body.style.overflow='';if(modal.open&&modal.close)modal.close();else modal.removeAttribute('open')} $$('[data-member]').forEach(c=>c.addEventListener('click',()=>openMember(c.dataset.member))); $$('[data-modal-close]').forEach(x=>x.addEventListener('click',closeMember)); modal?.addEventListener('cancel',e=>{e.preventDefault();closeMember()});

