const inquiryModal=$('[data-inquiry-modal]');
function openInquiry(){if(!inquiryModal)return;document.body.style.overflow='hidden';if(inquiryModal.showModal)inquiryModal.showModal();else inquiryModal.setAttribute('open','');}
function closeInquiry(){if(!inquiryModal)return;document.body.style.overflow='';if(inquiryModal.open&&inquiryModal.close)inquiryModal.close();else inquiryModal.removeAttribute('open');}
$$('[data-contact-open]').forEach(btn=>btn.addEventListener('click',()=>{closeMember();setTimeout(openInquiry,110)}));
$$('[data-inquiry-close]').forEach(btn=>btn.addEventListener('click',closeInquiry));
inquiryModal?.addEventListener('cancel',e=>{e.preventDefault();closeInquiry()});
function waFromForm(form,heading){const labels={reason:'Причина',name:'Имя',phone:'Телефон',company:'Компания / проект',service:'Интересует',message:'Комментарий'};const rows=[heading];[...form.elements].forEach(el=>{if(!el.name)return;const value=el.tagName==='SELECT'?el.selectedOptions[0]?.textContent:el.value;if(String(value||'').trim())rows.push(`${labels[el.name]||el.name}: ${value}`)});window.open(`${whatsappUrl}?text=${encodeURIComponent(rows.join('\n'))}`,'_blank','noopener,noreferrer');}
$('[data-inquiry-form]')?.addEventListener('submit',e=>{e.preventDefault();waFromForm(e.currentTarget,'Здравствуйте! Хочу связаться с командой SMM KADR.');closeInquiry()});
$('[data-contact-form]')?.addEventListener('submit',e=>{e.preventDefault();waFromForm(e.currentTarget,'Здравствуйте! Оставляю заявку с сайта SMM KADR.')});

$$('a[data-page-link]').forEach(a=>a.addEventListener('click',e=>{const u=new URL(a.href,location.href);if(u.origin!==location.origin||u.pathname===location.pathname||e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();document.body.classList.add('page-leave');setTimeout(()=>location.href=a.href,170)}));
